 50 │         head_disposition: GitHeadDisposition,
 51 │         allowed_ignored_paths: Vec<PathBuf>,
 52 │     ) -> Self {
 53 │         Self {
 54 │             canonical_root,
 55 │             head,
 56 │             head_disposition,
 57 │             allowed_ignored_paths,
 58 │         }
 59 │     }
