105 │     /// Re-observes the root, full commit, symbolic-HEAD state, and worktree
106 │     /// through the shell backend. These facts must never come from a native
107 │     /// repository handle cached before final release validation.
108 │     pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
109 │         self.shell.observe_git_commit_trust()
110 │     }
111 │ }
