  1 │ //! Central native-`gix`-first, `CommandRunner`-shell-fallback selection
  2 │ //! logic for [`GitDataSource`].
  3 │ 
  4 │ use std::path::{Path, PathBuf};
  5 │ 
  6 │ use callisto_model::{ApplyPermit, CommandRunner, CommitSha, TagName};
  7 │ 
  8 │ use crate::{GitCommit, GitDataSource, GitRepository, ShellGit, VcsError};
  9 │ 
 10 │ /// Selects between native `gix` ([`GitRepository`]) and a `CommandRunner`
 11 │ /// shell-out ([`ShellGit`]) per operation, so callers never branch on it.
 12 │ ///
 13 │ /// Construct via [`GitAccess::discover`], then call [`GitDataSource`]
 14 │ /// methods directly.
 15 │ ///
 16 │ /// **Fallback policy differs by operation category, deliberately:**
 17 │ ///
 18 │ /// - **Reads** ([`GitDataSource::list_tags`], [`GitDataSource::resolve_commit`],
 19 │ ///   [`GitDataSource::commits_since`]): fall back to shell on *any* `gix`
 20 │ ///   error (failed discovery, or a discovered repo's op failing) --
 21 │ ///   retrying a read can only help.
 22 │ /// - **Writes** ([`GitDataSource::create_tag`], [`GitDataSource::create_floating_major`]):
 23 │ ///   fall back *only* if `gix` was never discovered. A discovered repo's
 24 │ ///   result is authoritative -- retrying a failed mutation through a
 25 │ ///   different path risks masking a real failure, or double-applying a
 26 │ ///   partial mutation.
 27 │ pub struct GitAccess<'r> {
 28 │     native: Option<GitRepository>,
 29 │     shell: ShellGit<'r>,
 30 │ }
 31 │ 
 32 │ /// Fresh Git checkout facts used to bind a durable release intent to the
 33 │ /// exact repository it was validated against.
 34 │ ///
 35 │ /// This is intentionally evidence, not a lossy `bool`: consumers must retain
 36 │ /// the canonical root and complete `HEAD` they compare to source identity.
 37 │ /// Its fields are private so only the VCS observation path can construct it.
 38 │ #[derive(Debug, PartialEq, Eq)]
 39 │ pub struct GitCommitTrustEvidence {
 40 │     canonical_root: PathBuf,
 41 │     head: CommitSha,
 42 │     head_disposition: GitHeadDisposition,
 43 │     allowed_ignored_paths: Vec<PathBuf>,
 44 │ }
 45 │ 
 46 │ impl GitCommitTrustEvidence {
 47 │     pub(crate) fn new(
 48 │         canonical_root: PathBuf,
 49 │         head: CommitSha,
 50 │         head_disposition: GitHeadDisposition,
 51 │         allowed_ignored_paths: Vec<PathBuf>,
 52 │     ) -> Self {
 53 │         Self {
 54 │             canonical_root,
 55 │             head,
 56 │             head_disposition,
 57 │             allowed_ignored_paths,
 58 │         }
 59 │     }
 60 │ 
 61 │     pub fn canonical_root(&self) -> &Path {
 62 │         &self.canonical_root
 63 │     }
 64 │ 
 65 │     pub fn head(&self) -> &CommitSha {
 66 │         &self.head
 67 │     }
 68 │ 
 69 │     pub fn head_disposition(&self) -> GitHeadDisposition {
 70 │         self.head_disposition
 71 │     }
 72 │ 
 73 │     pub fn allowed_ignored_paths(&self) -> &[PathBuf] {
 74 │         &self.allowed_ignored_paths
 75 │     }
 76 │ }
 77 │ 
 78 │ /// Whether `HEAD` was attached to a symbolic reference when it was observed.
 79 │ /// A detached checkout is valid when its full [`CommitSha`] matches the
 80 │ /// release intent's source identity.
 81 │ #[derive(Clone, Copy, Debug, PartialEq, Eq)]
 82 │ pub enum GitHeadDisposition {
 83 │     Attached,
 84 │     Detached,
 85 │ }
