113 │ impl GitDataSource for GitAccess<'_> {
114 │     fn head_sha(&self) -> Result<CommitSha, VcsError> {
115 │         if let Some(repo) = &self.native {
116 │             if let Ok(sha) = repo.head_sha() {
117 │                 return Ok(sha);
118 │             }
119 │         }
120 │         self.shell.head_sha()
121 │     }
122 │ 
123 │     fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
124 │         if let Some(repo) = &self.native {
125 │             if let Ok(tags) = repo.list_tags(glob) {
126 │                 return Ok(tags);
127 │             }
128 │         }
129 │         self.shell.list_tags(glob)
130 │     }
131 │ 
132 │     fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
133 │         if let Some(repo) = &self.native {
134 │             if let Ok(sha) = repo.resolve_commit(refname) {
135 │                 return Ok(sha);
136 │             }
137 │         }
138 │         self.shell.resolve_commit(refname)
139 │     }
140 │ 
141 │     fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
142 │         if let Some(repo) = &self.native {
143 │             if let Ok(commits) = repo.commits_since(since_ref, pathspecs) {
144 │                 return Ok(commits);
145 │             }
146 │         }
147 │         self.shell.commits_since(since_ref, pathspecs)
148 │     }
149 │ 
150 │     fn create_tag(
151 │         &self,
152 │         name: &str,
153 │         target_sha: &CommitSha,
154 │         message: Option<&str>,
155 │         permit: &ApplyPermit,
156 │     ) -> Result<(), VcsError> {
157 │         if let Some(repo) = &self.native {
158 │             // Authoritative: a genuine gix failure must not be masked by
159 │             // silently retrying through the shell.
160 │             return repo.create_tag(name, target_sha, message, permit);
161 │         }
162 │         self.shell.create_tag(name, target_sha, message, permit)
163 │     }
164 │ 
165 │     fn create_floating_major(
166 │         &self,
167 │         major_name: &str,
168 │         target_sha: &CommitSha,
169 │         permit: &ApplyPermit,
170 │     ) -> Result<(), VcsError> {
171 │         if let Some(repo) = &self.native {
172 │             return repo.create_floating_major(major_name, target_sha, permit);
173 │         }
174 │         self.shell.create_floating_major(major_name, target_sha, permit)
175 │     }
176 │ }
